rank={n:i for i,n in enumerate(order)}
hasparent={n:False for n in order}
for line in open('/task/work/ava.tsv'):
    f=line.split('\t')
    q,t=f[0].split(';')[0],f[1].split(';')[0]
    if q==t: continue
    if rank[t]<rank[q]:
        hasparent[q]=True
asvs=[n for n in order if not hasparent[n]]
with open('/task/work/asv_map.tsv','w') as m, open('/task/output/asv.fasta','w') as out:
    for i,n in enumerate(asvs,1):
        aid=f'ASV{i:03d}'
        m.write(f'{aid}\t{n}\t{sizes[n]}\n')
        out.write(f'>{aid}\n{seqs[n]}\n')
print('n ASVs:', len(asvs))
